INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N041-01','CN0244','S041-01','原线水分流及设计容量','3.2.2、表3-2','2020排查报告历史原线：SCR 9000m³/a，废催化剂回收3000t/a；RO制纯水浓水141.7m³/a，TDS，经总排口外排；生活污水化粪池后经总排口送孟州市产业集聚区污水厂；烘干焙烧喷淋水含氨、收集回用于生产，补水500m³/a不是废水流量。滤渣60、边角料300、粉尘10.69t/a回用；再生粉尘4.76t/a HW49委外，均非水量。历史设计不是2026三级清洗技改；原PDF截图超时，采用可读正文。','WEB_COMPANY','公开文本摘录；未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N041-02','CN0063','S041-02','集团2026运行自述','工业废水段','调节、三级反应、MBR、RO及中水回用；集团宣称工业废水零排放。非独立监测，不推出全厂零排放；既有2025环评记录两级RO和三效蒸发，本篇未给级数、浓水、蒸发、废盐实际去向及流量，不补绘。','WEB_COMPANY','公开文本摘录；未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N041-03','CN0083','S041-03','一期历史排放总量','检索摘录','报告述一期废水排放5470.52t/a、COD0.148t/a、氨氮0.049t/a，满足ZBZL(2022)-79总量要求；统计年度及核算方式待查，非催化剂专股、非实测浓度。','WEB_PRIMARY','公开文本摘录；未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N041-04','CN0253','S041-04','新项目受理状态','2026-11-26转载','150t/a IPN项目环评受理，公示2026-11-27至12-10；并非竣工环保验收、审批或投产。','WEB_SECONDARY','公开文本摘录；未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N041-05','CN0253','S041-05','既有实验装置历史状态','检索摘录','12t/a实验装置2006-11批准、通环验〔2012〕0102号验收，报告述当时正常运行；不等于2026仍运行；与既有12t/a为同一装置。','WEB_COMPANY','公开文本摘录；未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N041-06','CN0292','S041-06','审批节点和产品单位','审批结果表','2026-05-22备案、07-03用地规划、11-12设计审查、11-17建设工程规划许可建字第3301112026GG0125613号。铜基催化剂标题5000缺单位；高纯氧化亚铜明确5000吨。非开工验收。','WEB_SECONDARY','公开文本摘录；未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N041-07','CN0293','S041-07','厂区沿革、生产线索','企业介绍','2003原名江西置顺化工传质有限公司，2007合资后更名；2017年47亩新三板工业园厂房建设，2018年2条网带窑、2台梭式窑，2023年新增隧道窑投运；2020年SCR尾气净化为废气用途，不是生产废水膜。','WEB_COMPANY','公开文本摘录；未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N041-08','CN0293','S041-08','联系地址','联系信息','萍乡高新技术工业园北区工业大道21号为网站联系地址，不能单独确证工厂门牌。','WEB_COMPANY','公开文本摘录；未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N041-09','CN0294','S041-07','子公司建设','企业介绍','2025年成立子公司，萍乡经开区160亩新厂建设，设计1万吨/年高比表载体；不认定已投产。','WEB_COMPANY','公开文本摘录；未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N041-10','CN0294','S041-09','载体项目计划','2026省重点新开工项目','项目列入计划，产品为高比表蜂窝陶瓷载体，不能作成品催化剂产能。','WEB_SECONDARY','公开文本摘录；未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N041-11','CN0295','S041-10','实验室范围及危废','拟审批正文','2400m²，1台挤出机、16套5–10mL与4套100mL微反性能测试设备、10台分析设备；明确不涉及中试及生产。含重金属/硝酸盐、首洗、标准液和离心液按废液分类委外；一般实验水经研发中心收集及园区处理，转载部分名称遮蔽；不猜补。总投资500万元是项目投资，不是污水投资。','WEB_SECONDARY','公开文本摘录；未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N041-12','CN0263','S041-11','许可变更原始审批','政府许可页','补充政府审批来源以核已有2024年91kt/a及2025年25kt/a许可差异，非新增生产规模；仍需逐厂处理水证据。','WEB_PRIMARY','公开文本摘录；未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N041-13','CN0230','S041-12','污水站工程进度','11月11日公示索引','5000t/a胺催化剂、50000t/a聚醚、2100t/a药用辅料项目污水站等规划许可证批后公示；仅索引，非建成投运。既有100t/d设计、5751800元中标不重复入库。','WEB_SECONDARY','公开文本摘录；未归档原件','2026-11-28');
